def find_reversible_primes(start: int, stop: int) -> list[int]:
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def reverse(n: int) -> int:
        return int(str(n)[::-1])

    primes = []
    for n in range(start, stop + 1):
        rev_n = reverse(n)
        if is_prime(n) and is_prime(rev_n) and n != rev_n:
            primes.append(n)
            # Check if the reversed number is within the range and not already added
            if start <= rev_n <= stop and rev_n not in primes:
                primes.append(rev_n)

    return sorted(primes)

def find_power_of_2_in_interval(n: int, m: int) -> int:
    from math import log2

    # Check if the interval contains a power of 2
    if int(log2(m)) > int(log2(n)):
        return 2**int(log2(m))

    # Adjust endpoints to exclude odd numbers
    n += n % 2
    m -= m % 2
    if n == m:
        return n

    # Recurse with halved endpoints and multiply the result by 2
    return 2 * find_power_of_2_in_interval(n // 2, m // 2)

def is_square_free_with_prime_factor_count(n: int) -> int:
    sP, p = set(), 2
    while n > 1 and p <= n**0.5:
        while not n % p:
            if p in sP:
                return 0  # n is divisible by the square of a prime
            sP.add(p)
            n //= p
        p += 1 + (p != 2)
    # Return 1 if even number of prime factors, -1 if odd
    return (-1) ** ((len(sP) + (n != 1)) % 2)

